  'Acting III (Period and Style)',
  'Acting III (Period and Style)',
  'Acting III (Period and Style) trains advanced undergraduate actors to perform heightened language, classical scenes, verse, period behavior, and stylized theatrical worlds with clarity, rigor, embodiment, and imagination. Students develop tools for Shakespeare, Greek tragedy, Restoration comedy, classical monologues, period manners, and style-specific physicality while keeping choices active, ethical, and accessible to contemporary audiences. The course prepares students for advanced acting, classical production work, auditions, dramaturgical collaboration, period/style performance, and capstone productions.',
  $act3json${"slug": "acting-iii-period-and-style", "title": "Acting III (Period and Style)", "description": "Acting III (Period and Style) trains advanced undergraduate actors to perform heightened language, classical scenes, verse, period behavior, and stylized theatrical worlds with clarity, rigor, embodiment, and imagination. Students develop tools for Shakespeare, Greek tragedy, Restoration comedy, classical monologues, period manners, and style-specific physicality while keeping choices active, ethical, and accessible to contemporary audiences. The course prepares students for advanced acting, classical production work, auditions, dramaturgical collaboration, period/style performance, and capstone productions.", "topics": [{"id": "9f003799-5b1b-47cd-bd2d-33aade0639ac", "type": "topic", "title": "Heightened Language and Text", "description": "Advanced actors must learn to treat complex language as action. This unit turns imagery, rhetoric, and formal structure into playable behavior.", "children": [{"id": "59e860a9-6931-44ee-9c01-332f64583418", "type": "subtopic", "title": "Rhetorical Action", "children": [{"id": "90c99945-387a-41db-95a5-563103e74473", "type": "concept", "title": "Antithesis, repetition, lists, questions, and appeals"}, {"id": "3a72b18f-b3cc-42b4-99bf-b4c25f0d231d", "type": "concept", "title": "Thought progression and tactical shifts"}, {"id": "d7fdb26b-f5fb-40b2-a496-592d5a07220c", "type": "concept", "title": "Rhetoric as behavior, not decoration"}], "description": "Students learn that heightened speech argues, seduces, attacks, mourns, bargains, and transforms."}, {"id": "a8a5cabf-e7de-4dda-b508-b210c276d560", "type": "subtopic", "title": "Imagery and Sensory Life", "children": [{"id": "c064637e-0fbd-4786-a237-682547845ee3", "type": "concept", "title": "Metaphor, simile, mythology, nature, and violence"}, {"id": "b3a60c95-a4f4-45c3-a6c0-584ee9a7bb80", "type": "concept", "title": "Personalizing imagery without flattening it"}, {"id": "5979495a-16ca-4e16-97c7-b6d2a9022591", "type": "concept", "title": "Physical response to language"}], "description": "Images become playable when they affect breath, body, and relationship."}, {"id": "f9d5110e-6f6f-428b-baed-84f8d3f1f902", "type": "subtopic", "title": "Clarity for the Audience", "children": [{"id": "86c5c9f1-96b3-49b1-8fa9-77a070d25f84", "type": "concept", "title": "Paraphrase and glossary work"}, {"id": "891b5c2d-21fd-4f7f-8788-e4cb8d231d58", "type": "concept", "title": "Operative words and syntax"}, {"id": "5813acf7-6d0f-4183-bb06-ecc4405a6dfc", "type": "concept", "title": "Balancing speed, precision, and urgency"}], "description": "The actor must make difficult text immediate and intelligible."}]}, {"id": "a69c3639-1b3d-4501-842d-57a8998a1bba", "type": "topic", "title": "Shakespeare's Verse and Scansion", "description": "Verse gives actors a map of thought, pressure, music, and disruption. Students learn to use meter without becoming mechanical.", "children": [{"id": "93d307ef-cb7f-4684-8b74-a62ac7682971", "type": "subtopic", "title": "Iambic Pentameter Basics", "children": [{"id": "17f1b98c-8ae4-4b65-9a7a-26824c1b9d16", "type": "concept", "title": "Iambs, pentameter, shared lines, feminine endings"}, {"id": "08e80055-d188-4fb4-a19f-97b0c2831f4b", "type": "concept", "title": "Regularity as structure"}, {"id": "941fce41-e049-41ed-a686-8f76615594ca", "type": "concept", "title": "Meter as breath and thought"}], "description": "Students learn the underlying pulse so they can notice when it changes."}, {"id": "b6948983-886a-4f73-a97e-673107867401", "type": "subtopic", "title": "Irregularity and Meaning", "children": [{"id": "cb10f83e-2f3b-495e-b2fd-8e9bca5c9e84", "type": "concept", "title": "Trochees, spondees, short lines, extra syllables"}, {"id": "0960e09b-8beb-43f4-a0ae-c0ae9551389e", "type": "concept", "title": "Broken rhythm and emotional turn"}, {"id": "f7e00d8a-81f9-4ab7-805b-39caa426ddd9", "type": "concept", "title": "Scansion choices as rehearsal questions"}], "description": "Departures from meter often reveal character pressure."}, {"id": "77f7d1f3-7206-44f0-b252-307b7e83cf14", "type": "subtopic", "title": "Verse in Performance", "children": [{"id": "bb5ea73a-0249-4503-9309-d492e97bbeff", "type": "concept", "title": "Line endings and enjambment"}, {"id": "333703c3-6ad2-4895-9160-8e70826a542e", "type": "concept", "title": "Caesura and breath"}, {"id": "3b9127b0-b3f1-4ebe-8304-3fef57a34f28", "type": "concept", "title": "Speaking verse as active thought"}], "description": "Scansion becomes useful only when embodied."}]}, {"id": "ba294e69-8bb3-4acf-a856-3d0e758c00ef", "type": "topic", "title": "Classical Scene Work", "description": "Classical scenes ask actors to combine scale, precision, rhetorical action, partner pressure, and emotional truth.", "children": [{"id": "e500bbc2-42ef-4272-9b0b-151e0492b2fa", "type": "subtopic", "title": "Status and Stakes", "children": [{"id": "a88ce081-f4f1-4665-9d33-a07e8c60aba0", "type": "concept", "title": "Rank, honor, family, state, religion, and reputation"}, {"id": "19867b7f-cc89-413c-9086-66706dee07e0", "type": "concept", "title": "Public versus private stakes"}, {"id": "c46fdc98-63a9-4140-93ad-5b5d925c8eb9", "type": "concept", "title": "Power shifts across the scene"}], "description": "Students raise the level of necessity without generalizing."}, {"id": "b78712e7-dbd9-4fb4-b2ea-bab55d951564", "type": "subtopic", "title": "Partner and Argument", "children": [{"id": "d5f8a257-79c2-4aea-8460-d6a2d5ed1b6e", "type": "concept", "title": "Listening through rhetoric"}, {"id": "cc937dee-1ee1-46b5-9a5a-ee65512b017a", "type": "concept", "title": "Counterargument and interruption"}, {"id": "4d0cb54a-956c-4d22-b57c-39c91d8e44ca", "type": "concept", "title": "Winning, losing, and changing tactics"}], "description": "Classical text is often a contest of will."}, {"id": "7a1dc52c-36e0-496d-b556-abad1b91844b", "type": "subtopic", "title": "Scale Without Indicating", "children": [{"id": "f1218df5-d400-4f01-bbb7-38042d9b0738", "type": "concept", "title": "Vocal energy, physical clarity, and stillness"}, {"id": "63591dcf-6ab1-4f79-8c3f-09a643a02e4c", "type": "concept", "title": "Avoiding declamation"}, {"id": "1cfa8e78-f25a-4afe-bc2c-8942287355bc", "type": "concept", "title": "Truth at theatrical scale"}], "description": "The unit teaches size rooted in action."}]}, {"id": "acaf8a21-40d5-4423-91a5-61086e5b94a5", "type": "topic", "title": "Restoration Comedy and Style", "description": "Restoration comedy trains wit, social performance, status, manners, tempo, and the danger beneath elegance.", "children": [{"id": "67e108d3-8e45-4509-b47c-60112bfdc40e", "type": "subtopic", "title": "World of Manners", "children": [{"id": "bb0408b9-eff9-4ee1-bdfa-03cb52ff2ef7", "type": "concept", "title": "Courtship, reputation, class, sex, money, and gossip"}, {"id": "477980aa-52aa-4c81-9fa0-4f85299f127e", "type": "concept", "title": "Public display and private desire"}, {"id": "06808ded-9c9a-45ee-8d09-35a3497a80d1", "type": "concept", "title": "Etiquette as tactic"}], "description": "Actors learn the rules of a society where appearance is action."}, {"id": "dc3843b6-e831-4342-81b4-d8f7e67427d6", "type": "subtopic", "title": "Wit and Tempo", "children": [{"id": "b9bfa632-d646-43b4-96a6-17ee6b7de56a", "type": "concept", "title": "Epigram, repartee, irony, and double meaning"}, {"id": "6f72612d-210d-4bae-b986-e2481083ba2e", "type": "concept", "title": "Cue pickup and verbal attack"}, {"id": "9a3895b7-e758-4bfb-956c-982844981533", "type": "concept", "title": "Listening for reversals"}], "description": "Comedy of manners depends on speed, intelligence, and precision."}, {"id": "699f5fcb-1cf4-4cf4-998e-cc4f48b6b22b", "type": "subtopic", "title": "Physical Style", "children": [{"id": "8efffbbb-73aa-462c-90f3-93ffe8294dc3", "type": "concept", "title": "Bows, fans, hats, handkerchiefs, swords, and chairs"}, {"id": "ad4084fc-9463-443c-928c-d93b9f0519c4", "type": "concept", "title": "Silhouette and gesture"}, {"id": "d032fc25-2e71-43fa-85b5-26fb8d5560d6", "type": "concept", "title": "Elegance under pressure"}], "description": "The actor's body carries period codes."}]}, {"id": "e105f697-d8ae-4909-b871-6d6820d9af72", "type": "topic", "title": "Greek Tragedy", "description": "Greek tragedy introduces scale, chorus, myth, public grief, ritual action, and ethical conflict larger than private psychology.", "children": [{"id": "8499fae5-cb55-47aa-963a-c4e4ea9fe6d2", "type": "subtopic", "title": "Myth and Civic Stakes", "children": [{"id": "70b31568-1297-4b48-a239-b7b4bd8c34e8", "type": "concept", "title": "Oikos and polis"}, {"id": "0030ccdf-6c2c-409d-b6db-28e8c7ee63ba", "type": "concept", "title": "Fate, law, kinship, revenge, and supplication"}, {"id": "3485827a-2ade-4c9d-8c5b-4d70bd33d588", "type": "concept", "title": "Heroic scale and consequence"}], "description": "Students connect personal action to household, city, divine order, and public memory."}, {"id": "42ab9370-ed7e-4c3d-9bd2-5ac27e8d0460", "type": "subtopic", "title": "Chorus and Collective Voice", "children": [{"id": "7082d727-a56a-424f-a19f-257563b077cb", "type": "concept", "title": "Unison, counterpoint, chant, lament, and movement pattern"}, {"id": "00f3f7c6-a510-4ea6-8b62-5749863050b1", "type": "concept", "title": "Chorus as character, witness, and community"}, {"id": "e79011ac-ce45-4cf0-8d9c-35e282c1b2b5", "type": "concept", "title": "Breath and group focus"}], "description": "Chorus work develops ensemble rhythm and public witnessing."}, {"id": "3d70b2fb-28ce-43b6-b229-7bea748a3d8f", "type": "subtopic", "title": "Messenger, Lament, and Ritual", "children": [{"id": "d2e9ab5c-2a9a-4b64-ba6c-3dd310c16540", "type": "concept", "title": "Narrating offstage violence"}, {"id": "e3cc14f2-7957-4150-88ad-1876e11160d5", "type": "concept", "title": "Kommos and lament"}, {"id": "f2d56e1b-f3b1-4257-85d5-f061b2e402cd", "type": "concept", "title": "Mask, gesture, and ceremonial action"}], "description": "Students explore forms that require clarity and heightened presence."}]}, {"id": "4915b5f8-987f-40a5-b73e-b82cd56b1616", "type": "topic", "title": "Period Movement and Manners", "description": "Period style is not costume trivia; it shapes status, desire, access, gender, class, space, and timing.", "children": [{"id": "65deb51b-69ee-41f2-bb48-c9e85cbdad9a", "type": "subtopic", "title": "Etiquette as Dramatic Action", "children": [{"id": "8b3e4426-39c2-4251-a54f-f50e9337d7ce", "type": "concept", "title": "Greeting, bowing, sitting, entering, exiting, and address"}, {"id": "27fb29b1-f194-4622-baf6-02f17388a3d2", "type": "concept", "title": "Permission, distance, touch, and rank"}, {"id": "101218c8-9963-490c-be10-0f909f35b17b", "type": "concept", "title": "Politeness as control or attack"}], "description": "Manners become playable tactics."}, {"id": "a4f421ca-f7f8-4f3f-8cb0-67f2f846747e", "type": "subtopic", "title": "Objects and Costume Logic", "children": [{"id": "e7e99f05-07a0-4a27-afd5-cb266dd901d3", "type": "concept", "title": "Fans, hats, gloves, swords, skirts, corsets, coats, and canes"}, {"id": "e6b4b012-7d1e-4c04-835a-6aaf966e0835", "type": "concept", "title": "Handling objects with purpose"}, {"id": "5b7cd3df-959f-4de8-a8c8-35145bc5a198", "type": "concept", "title": "Costume constraints as creative information"}], "description": "Props and clothing change behavior."}, {"id": "a7db6828-36e3-4497-9e8f-97c001f0f828", "type": "subtopic", "title": "Historical Research and Imagination", "children": [{"id": "bb5ffd57-b9fa-42b4-87a8-8002a3893efb", "type": "concept", "title": "Period images and etiquette manuals"}, {"id": "4598cbd9-ab66-45bc-a65f-f91ead8ae166", "type": "concept", "title": "Class, gender, race, empire, and labor context"}, {"id": "ca1b9395-2160-45d6-bf93-0319b54ee4f5", "type": "concept", "title": "Balancing accuracy and theatrical readability"}], "description": "Students use research to fuel choices without museum stiffness."}]}, {"id": "b649b52c-ad0e-4036-9a14-63b0690c2926", "type": "topic", "title": "Style and Physicality", "description": "Different theatrical styles demand different bodies. This unit trains actors to make physical choices that reveal the rules of the world.", "children": [{"id": "4132fc50-886a-4a15-be25-8d6b83ace14c", "type": "subtopic", "title": "Style Rules", "children": [{"id": "ec5012a3-0773-4188-9108-36fb87f17ffb", "type": "concept", "title": "Gesture size, tempo, posture, eye contact, and distance"}, {"id": "0844dfa3-0486-426d-b7f8-75260f7be855", "type": "concept", "title": "Realism versus heightened form"}, {"id": "896beb73-474b-437f-ac69-f38cb1f29e2d", "type": "concept", "title": "Consistency across the ensemble"}], "description": "Students identify what each world permits, forbids, and rewards."}, {"id": "4ca49890-52cc-438c-9947-f8656332bdb1", "type": "subtopic", "title": "Physical Score", "children": [{"id": "bbaa4b52-bd04-471f-8bf1-21d073fafa6d", "type": "concept", "title": "Entrance, transition, gesture, stillness, and exit"}, {"id": "8e4c1708-43c3-4651-a72e-e2aeab3cdb7b", "type": "concept", "title": "Rhythm and spatial pattern"}, {"id": "f3068e75-af25-48b0-b4ad-433abd4c2ee1", "type": "concept", "title": "Physical score tied to objective"}], "description": "Actors build repeatable movement structures."}, {"id": "3d846844-fd46-4126-aa91-4f398c93cbf7", "type": "subtopic", "title": "Transformation and Safety", "children": [{"id": "512021c2-721d-4cec-b034-0e8aaaabf4f7", "type": "concept", "title": "Warm-up and cool-down"}, {"id": "76ac309d-2fb8-48d8-95ec-4dedbcc8fdf1", "type": "concept", "title": "Range without strain"}, {"id": "2bba425c-19bf-4e08-a47e-9e6996a0896b", "type": "concept", "title": "Avoiding caricature and stereotype"}], "description": "Stylization should expand range while protecting bodies."}]}, {"id": "fa0b4b02-7573-4c4e-b19a-910375763910", "type": "topic", "title": "Verse Speaking", "description": "Verse speaking integrates breath, thought, rhetoric, music, and audience address. The goal is clarity with energy.", "children": [{"id": "206306f8-3d7b-4a77-95a3-e3174283760d", "type": "subtopic", "title": "Breath and Line", "children": [{"id": "e6c49b7c-63e6-4c0a-963e-78f32aeba15d", "type": "concept", "title": "Line endings, shared lines, and caesura"}, {"id": "ae85e34d-b68a-414e-964f-08d7b8c91189", "type": "concept", "title": "Breath as choice, not punctuation reflex"}, {"id": "5ef0ca3d-c5fa-46f3-aca9-58723275b6d3", "type": "concept", "title": "Sustaining thought through long syntax"}], "description": "Students learn how verse organizes breath and thought."}, {"id": "66690f45-617d-4985-8511-039fbda6527d", "type": "subtopic", "title": "Operative Words", "children": [{"id": "f7dad5ce-a3e2-49bb-bfff-335be47f9fb5", "type": "concept", "title": "Stress, contrast, repetition, and escalation"}, {"id": "41d67cd5-ebac-4218-b58c-df08004aa5fa", "type": "concept", "title": "Antithesis and lists"}, {"id": "e169545d-701f-4b70-874c-13f37baa5409", "type": "concept", "title": "Avoiding equal-weight delivery"}], "description": "Actors choose words that carry action and argument."}, {"id": "44f6fc4b-2646-43d7-9cef-f6beabdda551", "type": "subtopic", "title": "Audience and Address", "children": [{"id": "4f19c816-62fe-474e-a34b-b642a6f0a558", "type": "concept", "title": "Soliloquy, aside, direct address, and rhetorical question"}, {"id": "6a7197ac-d905-44c3-8d0d-78242b0620e5", "type": "concept", "title": "Inviting the audience into thought"}, {"id": "5597b547-93ce-40a4-8799-34c181356dfc", "type": "concept", "title": "Maintaining partner reality"}], "description": "Classical language often thinks aloud in public."}]}, {"id": "3deb0f88-f390-4628-9b19-776aef331694", "type": "topic", "title": "Classical Monologues", "description": "Monologues teach actors to hold argument, image, rhythm, audience relationship, and transformation alone on stage.", "children": [{"id": "d7fbcbed-c0a8-4ae5-b47d-930f1964d904", "type": "subtopic", "title": "Selection and Cutting", "children": [{"id": "76669861-6fde-4bff-be77-6a3ab4cd4cad", "type": "concept", "title": "Contrast, length, context, and audition usefulness"}, {"id": "012d0b90-fe7e-447e-b290-93311f560045", "type": "concept", "title": "Clean cuts that preserve argument"}, {"id": "c097d88d-085e-4b05-b1a2-6878f6a535c9", "type": "concept", "title": "Avoiding overused pieces unless freshly owned"}], "description": "Students choose material that fits age, range, and training goals."}, {"id": "a827b010-6dec-45ae-89b2-197781369042", "type": "subtopic", "title": "Argument and Journey", "children": [{"id": "6dae7dde-f92e-4af6-9b3c-a37f79494757", "type": "concept", "title": "Opening condition and final condition"}, {"id": "e3b23d5d-9470-4a61-baf1-fc0dfde34fd8", "type": "concept", "title": "Turns, discoveries, and tactical shifts"}, {"id": "5090c17c-8f28-4064-95fd-f88f2736e21c", "type": "concept", "title": "Building to a necessary end"}], "description": "A monologue must change."}, {"id": "e0316e69-1140-4b43-83fa-ad2df23ea1e1", "type": "subtopic", "title": "Performance Frame", "children": [{"id": "763506a5-e3c2-4745-a80a-928ddc68f77e", "type": "concept", "title": "Slate and setup"}, {"id": "1b20d7b5-82d8-4657-8446-fa1c31822ecc", "type": "concept", "title": "Focus point and imagined partner"}, {"id": "f4545650-4329-47fa-bac4-b81e137ad38d", "type": "concept", "title": "Recovery, pace, and final beat"}], "description": "Students practice presentation skills without losing scene reality."}]}, {"id": "8fa69436-28fc-446a-8b95-fcd26acbba58", "type": "topic", "title": "Performing Classical Scenes", "description": "The final unit asks students to integrate text work, style, voice, body, research, and partner action in performance.", "children": [{"id": "4bcdf784-62db-47a5-9dfc-a783fc09e8d0", "type": "subtopic", "title": "Integration Rehearsal", "children": [{"id": "82ee7b37-d782-4a80-ac13-56b778d46cfc", "type": "concept", "title": "Text score, movement score, and character stakes"}, {"id": "07b009cb-108a-4ebd-b76f-4dc70653734c", "type": "concept", "title": "Partner notes and run logs"}, {"id": "47d7687b-c1d8-4dc0-afbb-35ffe054b87e", "type": "concept", "title": "Polishing while staying alive"}], "description": "Students bring analysis and style into repeatable rehearsal practice."}, {"id": "17cc744d-d338-4b0f-8887-37d759c0ad87", "type": "subtopic", "title": "Design and Space Awareness", "children": [{"id": "0e2aae96-f417-45fb-a4ab-06f7d5b20667", "type": "concept", "title": "Thrust, proscenium, black box, outdoor, and found spaces"}, {"id": "43e062a2-d87c-4497-a936-9d794cd5b0d3", "type": "concept", "title": "Costume/prop placeholders"}, {"id": "7719d9d8-3ef4-4464-b064-8e400c937764", "type": "concept", "title": "Sightlines, levels, and audience address"}], "description": "Classical style changes in different spaces and production concepts."}, {"id": "82638e8e-be75-4ef2-83fe-a92ac9315c22", "type": "subtopic", "title": "Reflection and Adaptation", "children": [{"id": "0d68a548-f88f-4385-bddd-8ac5ffbfb39b", "type": "concept", "title": "What style choices clarified the text"}, {"id": "975a7ce3-cd9e-41bc-9403-6b1043980cde", "type": "concept", "title": "Modern casting, translation, adaptation, and access"}, {"id": "5f1aad05-fd4e-4ff6-9a37-fdd3c5189933", "type": "concept", "title": "Next steps for auditions, Acting IV, and production work"}], "description": "Students learn to evaluate classical performance ethically and imaginatively."}]}, {"id": "fe5ac576-d102-4dcf-b2bd-23ccd9bd809c", "type": "topic", "title": "Ethics, Adaptation, and Contemporary Relevance", "description": "A world-class period/style course should ask how classical work is revived now: who speaks it, who is centered, and what choices make it responsible.", "children": [{"id": "6e76d77d-6177-4353-a4b5-58cb0b0a5584", "type": "subtopic", "title": "Canon and Power", "children": [{"id": "4f13d7d5-f2ab-4c4c-a7b1-bc943b8a9e75", "type": "concept", "title": "Race, gender, class, empire, and language"}, {"id": "2faca623-f0e6-49d1-99fd-87423dbba0dc", "type": "concept", "title": "Access to training and casting"}, {"id": "e9c37633-21f0-43a7-8674-4d1c4975928a", "type": "concept", "title": "Canon expansion and repertory choice"}], "description": "Students examine the institutions behind classical repertory."}, {"id": "cbab7c6b-c64f-4ab9-aba3-4526c84ad665", "type": "subtopic", "title": "Adaptation Choices", "children": [{"id": "2980ee12-7018-493a-8088-86f3aa134e40", "type": "concept", "title": "Modern dress, translation, cuts, doubling, and relocation"}, {"id": "f76815b9-e503-40a7-8d04-b820f77f76ef", "type": "concept", "title": "What changes and what remains"}, {"id": "fabee79b-ae12-43e0-bf25-c01afe1126cb", "type": "concept", "title": "Evidence-based adaptation"}], "description": "Actors learn how concept changes performance responsibility."}, {"id": "90cadf05-870b-4371-a9c9-2227bfc0399f", "type": "subtopic", "title": "Audience Accessibility", "children": [{"id": "03ea0c78-cc9c-4680-a1a9-981477cadf40", "type": "concept", "title": "Plain sense and vocal clarity"}, {"id": "ee10803f-a9c1-41ab-ac70-f400294e89f7", "type": "concept", "title": "Program/context materials"}, {"id": "76e82a46-0485-4d84-a6d8-3f7e05361e85", "type": "concept", "title": "Inclusive rehearsal and performance practices"}], "description": "Classical work should be clear and welcoming, not gatekept."}]}], "dbBacked": true}$act3json$::jsonb,
